// One item per variant that has a model number or barcode and is due a search.
const s = $('Discover settings').first().json;
const day = 864e5;
const log = {};
for (const r of $('Get search log').all()) log[r.json.product_key] = r.json;

const due = [];
for (const page of $('Get my products').all()) {
  for (const v of page.json.data.productVariants.nodes) {
    const mpn = String((s.mpn_source === 'sku' ? v.sku : (v.mpn?.value || v.product.mpn?.value)) || '').trim();
    const gtin = v.barcodes.nodes.map(b => String(b.value).replace(/\D/g, '')).find(b => b.length >= 8) || '';
    if (!mpn && gtin.length < 8) continue;                       // nothing to match on: see "Make it your own"
    const last = log[v.id];
    const age = last ? (Date.now() - new Date(last.last_searched_at)) / day : 9999;
    const every = last?.listings_found > 0 ? s.research_with_listings_days : s.research_without_listings_days;
    if (age < every) continue;
    const strong = /\d/.test(mpn) && !/\s/.test(mpn) && mpn.replace(/[^A-Za-z0-9]/g, '').length >= 6;
    due.push({ json: { product_key: v.id, sku: v.sku, mpn, gtin, brand: v.product.vendor, age,
      title: v.product.title + (v.title === 'Default Title' ? '' : ' ' + v.title),
      query: mpn ? (strong ? mpn : `${v.product.vendor} ${mpn}`) : gtin } });
  }
}
return due.sort((a, b) => b.json.age - a.json.age).slice(0, s.discovery_batch);

