// Turn each search into competitor listings, keeping only exact matches.
const s = $('Discover settings').first().json;
const sent = $('Pick products to search').all();
const results = $input.all();
const skip = [s.own_domain, ...s.exclude_domains].map(d => d.toLowerCase().replace(/^www\./, ''));
const host = u => (String(u).match(/^https?:\/\/([^/?#:]+)/i) || [])[1]?.toLowerCase().replace(/^www\./, '');
const DROP = /^(srsltid|utm_[a-z]+|gclid|variant|currency|country)$/i;
const cleanUrl = u => {
  const [base, q = ''] = String(u).split('#')[0].split('?');
  const kept = q.split('&').filter(kv => kv && !DROP.test(kv.split('=')[0]));
  return base + (kept.length ? '?' + kept.join('&') : '');
};

// Model number as a whole token, any separator: DS-2CD2366G2-I matches "ds 2cd2366g2 i", not DS-2CD2366G2-IU.
const chars = m => String(m).toUpperCase().replace(/[^A-Z0-9]/g, '').split('');
const titleRe = m => new RegExp('(^|[^A-Z0-9])' + chars(m).join('[\\s\\-_/.]?') + '(?![A-Z0-9]|-[A-Z0-9])');
const slugRe = m => new RegExp('(^|[^A-Z0-9])' + chars(m).join('[\\-_.]?') + '(?![A-Z0-9])');
const PACK = /\b(\d+|two|three|four|twin)[\s-]*(pack|pk)\b|\bpack of \d+|\bbundle\b|\bkit\b/i;

function match(q, title, url) {
  const T = String(title || '').toUpperCase(), U = String(url || '').split('?')[0].toUpperCase(); // path only: Google links carry the query
  if (PACK.test(title) && !PACK.test(q.title)) return null;          // a 2-pack isn't your single camera
  if (q.gtin && (T + ' ' + U).includes(q.gtin)) return { by: 'gtin', confidence: 1 };
  if (!q.mpn) return null;
  const strong = /\d/.test(q.mpn) && !/\s/.test(q.mpn) && q.mpn.replace(/[^A-Za-z0-9]/g, '').length >= 6;
  if (!strong && !T.includes(String(q.brand).toUpperCase())) return null; // short names need the brand
  if (titleRe(q.mpn).test(T)) return { by: 'mpn', confidence: strong ? 1 : 0.9 };
  if (slugRe(q.mpn).test(U)) return { by: 'mpn_url', confidence: strong ? 0.85 : 0.75 };
  return null;
}

function offersFrom(items = []) {
  const out = [];
  for (const it of items) {
    if (it.type === 'organic' && it.price?.current)
      out.push({ seller: it.website_name || it.domain, url: it.url, title: it.title, price: it.price.current, currency: it.price.currency });
    if (it.type === 'knowledge_graph')
      for (const sub of it.items || []) for (const el of sub.items || [])
        if (el.type === 'knowledge_graph_shopping_element' && el.price?.current)
          out.push({ seller: el.source, url: el.url, title: el.title, price: el.price.current, currency: el.price.currency });
    if ((it.type === 'popular_products' || it.type === 'shopping') && Array.isArray(it.items))
      for (const el of it.items) if (el.price?.current)
        out.push({ seller: el.seller || el.source, url: el.url, title: el.title, price: el.price.current, currency: el.price.currency });
  }
  return out;
}

const out = [];
const now = new Date().toISOString();
sent.forEach((p, i) => {
  const q = p.json;
  const task = results[i]?.json?.tasks?.[0];
  if (task?.status_code !== 20000) {
    out.push({ json: { kind: 'failed', query: q.query, error: task?.status_message || String(results[i]?.json?.error?.message || 'no response').slice(0, 200) } });
    return;
  }
  let kept = 0, rejected = 0;
  for (const o of offersFrom(task.result?.[0]?.items)) {
    const d = host(o.url);
    const m = d && o.currency === s.currency && !skip.some(x => d === x || d.endsWith('.' + x)) && match(q, o.title, o.url);
    if (!m) { rejected++; continue; }
    kept++;
    const url = cleanUrl(o.url);
    out.push({ json: { kind: 'listing', listing_key: q.product_key + '|' + url, product_key: q.product_key,
      sku: q.sku, mpn: q.mpn, gtin: q.gtin, product_title: q.title, url, domain: d,
      seller: String(o.seller || d).slice(0, 80), listing_title: o.title, matched_by: m.by, confidence: m.confidence,
      last_price: Number(o.price), currency: o.currency, in_stock: null, status: 'ok', method: 'search',
      last_checked_at: now, last_change: 0, pending_price: 0 } });
  }
  out.push({ json: { kind: 'search', product_key: q.product_key, query: q.query, last_searched_at: now,
    listings_found: kept, rejected, cost_usd: Number(task.cost || 0) } });
});
return out;

// Fetch robots.txt once per site, drop what it disallows, and plan a polite gap per site.
// RFC 9309: a 4xx means no rules; a 5xx or no answer means treat the whole site as disallowed.
const s = $('Recapture settings').first().json;
const token = s.robots_agent.toLowerCase();
const originOf = u => (String(u).match(/^(https?:\/\/[^/?#]+)/i) || [])[1]?.toLowerCase();
const pathOf = u => String(u).replace(/^https?:\/\/[^/?#]+/i, '').split('#')[0] || '/';

function parseRobots(txt) {
  const groups = [];
  let cur = null, lastWasAgent = false;
  for (const raw of String(txt).split(/\r?\n/)) {
    const m = raw.replace(/#.*$/, '').trim().match(/^([A-Za-z-]+)\s*:\s*(.*)$/);
    if (!m) continue;
    const key = m[1].toLowerCase(), val = m[2].trim();
    if (key === 'user-agent') {
      if (!lastWasAgent) groups.push(cur = { agents: [], rules: [], delay: null });
      cur.agents.push(val.toLowerCase());
      lastWasAgent = true;
      continue;
    }
    lastWasAgent = false;
    if (!cur) continue;
    if ((key === 'allow' || key === 'disallow') && val) cur.rules.push({ allow: key === 'allow', path: val });
    if (key === 'crawl-delay' && !isNaN(Number(val))) cur.delay = Number(val);
  }
  const mine = groups.filter(g => g.agents.some(a => a !== '*' && token.includes(a)));
  const chosen = mine.length ? mine : groups.filter(g => g.agents.includes('*'));
  return { rules: chosen.flatMap(g => g.rules), delay: chosen.map(g => g.delay).find(d => d != null) ?? null };
}
const toRegex = p => {
  const end = p.endsWith('$');
  const body = (end ? p.slice(0, -1) : p).split('*').map(x => x.replace(/[.+?^${}()|[\]\\]/g, '\\$&')).join('.*');
  return new RegExp('^' + body + (end ? '$' : ''));
};
function allowed(rules, path) {
  let best = null;                       // the longest matching rule wins; Allow wins a tie
  for (const r of rules) if (toRegex(r.path).test(path) &&
      (!best || r.path.length > best.path.length || (r.path.length === best.path.length && r.allow))) best = r;
  return !best || best.allow;
}

const rows = $input.all().map(i => i.json);
const robots = {};
for (const origin of [...new Set(rows.map(r => originOf(r.url)))]) {
  try {
    const res = await this.helpers.httpRequest({ url: origin + '/robots.txt', returnFullResponse: true,
      ignoreHttpStatusErrors: true, timeout: 15000, headers: { 'User-Agent': s.user_agent } });
    robots[origin] = res.statusCode >= 500 ? { rules: [{ allow: false, path: '/' }] }
      : res.statusCode >= 400 ? { rules: [] } : parseRobots(res.body);
  } catch (e) {
    robots[origin] = { rules: [{ allow: false, path: '/' }] };
  }
}

// Interleave sites so one site is never hit twice inside its gap (min_delay_seconds or its Crawl-delay).
const queues = {};
const out = [];
for (const r of rows) {
  const origin = originOf(r.url);
  if (allowed(robots[origin].rules, pathOf(r.url))) (queues[origin] ||= []).push(r);
  else out.push({ json: { ...r, fetch: false } });
}
let clock = 0;
const lastHit = {};
while (Object.values(queues).some(q => q.length)) {
  for (const [origin, q] of Object.entries(queues)) {
    if (!q.length) continue;
    const gap = Math.max(s.min_delay_seconds, robots[origin].delay || 0);
    const ready = origin in lastHit ? Math.max(clock, lastHit[origin] + gap) : clock;
    out.push({ json: { ...q.shift(), fetch: true, wait_seconds: Math.ceil(ready - clock) } });
    clock = lastHit[origin] = ready;
  }
}
return out;

// Read the price from one page: JSON-LD Product offers first, then price meta tags, then itemprop.
// Reads a plain HTTP Request response or a Firecrawl /v2/scrape response.
const s = $('Recapture settings').first().json;
const src = $('Loop Over Items').first().json;           // the listing being read
const r = $input.first().json;
const fc = $prevNode.name === 'Firecrawl scrape';        // which request fed this run
const via = fc ? 'firecrawl' : 'http';
const html = String((fc ? r.data?.rawHtml : (r.body ?? r.data)) || '');
const status = Number(fc ? r.data?.metadata?.statusCode : r.statusCode) || 0;
const errMsg = String(r.error?.message ?? r.error ?? '');
const num = v => { const n = Number(String(v ?? '').replace(/[^0-9.]/g, '')); return n > 0 ? n : null; };
const clean = v => String(v).toUpperCase().replace(/[^A-Z0-9]/g, '');
const ours = [src.mpn, src.gtin, src.sku].filter(Boolean).map(clean);
const idsOf = o => ['sku', 'mpn', 'gtin', 'gtin8', 'gtin12', 'gtin13', 'gtin14'].map(k => o?.[k]).filter(Boolean).map(clean);

function fromJsonLd(h) {
  const re = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  const found = [];
  let m;
  while ((m = re.exec(h))) {
    let data;
    try { data = JSON.parse(m[1].trim()); } catch (e) { continue; }
    for (const n of [].concat(data).flatMap(d => d?.['@graph'] || [d])) {
      if (![].concat(n?.['@type'] || []).some(t => /Product/i.test(t))) continue;
      for (const o of [].concat(n.offers || [])) {
        for (const x of o?.offers ? [].concat(o.offers) : [o]) {      // AggregateOffer holds nested offers
          const price = num(x?.price ?? x?.lowPrice ?? x?.priceSpecification?.price);
          if (!price) continue;
          const avail = String(x?.availability || o?.availability || '');
          found.push({ price, how: 'jsonld', ids: [...idsOf(x), ...idsOf(n)],
            currency: x?.priceCurrency || o?.priceCurrency || x?.priceSpecification?.priceCurrency || null,
            in_stock: avail ? /InStock|LimitedAvailability|PreOrder|BackOrder/i.test(avail) : null });
        }
      }
    }
  }
  // On a page with several variants, prefer the offer that carries your model number or barcode.
  return found.find(f => f.ids.some(id => ours.includes(id))) || found[0] || null;
}
function fromMeta(h) {
  const p = h.match(/<meta[^>]+(?:property|name)=["'](?:product|og):price:amount["'][^>]*content=["']([^"']+)["']/i)
         || h.match(/<meta[^>]+content=["']([^"']+)["'][^>]*(?:property|name)=["'](?:product|og):price:amount["']/i);
  if (p && num(p[1])) {
    const c = h.match(/(?:product|og):price:currency["'][^>]*content=["']([^"']+)["']/i);
    return { price: num(p[1]), currency: c ? c[1] : null, in_stock: null, how: 'meta' };
  }
  const ip = h.match(/itemprop=["']price["'][^>]*content=["']([^"']+)["']/i);
  return ip && num(ip[1]) ? { price: num(ip[1]), currency: null, in_stock: null, how: 'itemprop' } : null;
}

const found = html ? (fromJsonLd(html) || fromMeta(html)) : null;
const head = html.slice(0, 6000).toLowerCase();
const walls = ['just a moment', 'verify you are human', 'checking your browser', 'access denied', 'captcha',
               'cf-chl', 'attention required', 'request unsuccessful', 'are you a robot', 'pardon our interruption'];
const blocked = !found && (fc || [302, 303, 307, 401, 403, 503].includes(status) || /403|access denied|ECONNRESET/i.test(errMsg)
                           || walls.some(w => head.includes(w)));

// Fetch page doesn't follow redirects. A permanent one (301, 308) saves the new address, which goes back through
// the robots check on the next run; a temporary one (302, 303, 307) is usually a bot check, so it counts as blocked.
const loc = !fc && [301, 308].includes(status) && (r.headers?.location || r.headers?.Location);
const moved = loc && (/^https?:/i.test(loc) ? loc : src.url.match(/^https?:\/\/[^/]+/i)[0] + (loc.startsWith('/') ? '' : '/') + loc);
// A 429 asks you to slow down: wait out Retry-After (seconds or a date; an hour if it's missing), no Firecrawl.
const ra = r.headers?.['retry-after'];
const raSec = ra ? (isNaN(Number(ra)) ? (Date.parse(ra) - Date.now()) / 1000 : Number(ra)) : NaN;
const retrySec = Number.isFinite(raSec) ? raSec : 3600;

// Start from what the table already holds, so a failed read never wipes the last good price.
const row = { status: 'ok', method: via, url: src.url, last_checked_at: new Date().toISOString(), last_price: src.last_price,
              in_stock: src.in_stock, last_change: 0, pending_price: src.pending_price || 0 };
const last = Number(src.last_price) || 0;
if (moved) Object.assign(row, { status: 'moved', url: moved, last_checked_at: new Date(0).toISOString() });
else if (!fc && status === 429) Object.assign(row, { status: 'rate_limited',
  last_checked_at: new Date(Date.now() + Math.max(retrySec, 60) * 1000 - s.recapture_every_hours * 36e5).toISOString() });
else if (blocked) row.status = 'blocked';
else if (!found) row.status = html ? 'no_price' : 'error';
else if (found.currency && found.currency !== s.currency) row.status = 'wrong_currency';
else {
  row.method = via + ':' + found.how;
  const jump = last && Math.abs(found.price - last) / last > s.max_price_move;
  const confirmed = row.pending_price && Math.abs(found.price - row.pending_price) / row.pending_price < 0.02;
  if (jump && !confirmed) Object.assign(row, { status: 'suspect', pending_price: found.price }); // wait for a second reading
  else Object.assign(row, { last_price: found.price, in_stock: found.in_stock, pending_price: 0,
                            last_change: last ? Math.round((found.price - last) * 100) / 100 : 0 });
}

// Firecrawl only for blocked pages, and only up to firecrawl_per_run pages a run.
let try_firecrawl = false;
if (row.status === 'blocked' && !fc && s.use_firecrawl) {
  const st = $getWorkflowStaticData('global');
  if (st.run !== $execution.id) Object.assign(st, { run: $execution.id, firecrawl: 0 });
  try_firecrawl = st.firecrawl++ < s.firecrawl_per_run;
}
return [{ json: { listing_key: src.listing_key, row, try_firecrawl } }];

